-- =====================================================================
-- SUPPLY CHAIN & OPERATIONS ANALYTICS  (Growthskale Final Project)
-- Dataset : inventory-supply-chain-v1.0.0-analysis_1.xlsx  (single table, 18,000 purchase orders)
-- Dialect : standard SQL - tested on SQLite 3.53; also valid for MySQL 8 / PostgreSQL
--
-- SCOPE (per Growthskale correction notice: single table, skip questions the data cannot answer)
--   Answered fully   : Q1, Q4, Q5, Q6, Q8, Q14, Q15, Q16, Q18, Q20
--   Answered partly  : Q3, Q11, Q12, Q19  (warehouse-level, no opening stock / product data)
--   SKIPPED          : Q2, Q7, Q9, Q10, Q13, Q17 - they need product names, inventory balances
--                      or reorder levels, which are not in the dataset.
--
-- Supplier lead time and reliability are NOT columns in the data. They are derived from the dates:
--   lead time   = received_at - ordered_at
--   reliability = % of delivered orders received no more than 3 days after expected_at
-- =====================================================================

-- ---------------------------------------------------------------------
-- PART 0 : TABLE CREATION AND DATA LOAD
-- The flat workbook is split into suppliers, warehouses and purchase_orders.
-- ---------------------------------------------------------------------
DROP VIEW  IF EXISTS v_active_po;
DROP TABLE IF EXISTS purchase_orders;
DROP TABLE IF EXISTS suppliers;
DROP TABLE IF EXISTS warehouses;
DROP database SupplyChain;
create database SupplyChain;
CREATE TABLE suppliers (
    supplier_id        VARCHAR(10) PRIMARY KEY,
    supplier_country   VARCHAR(5)  NOT NULL,
    avg_lead_time_days DECIMAL(6,2),   -- derived below from actual PO dates
    reliability_score  DECIMAL(5,2)    -- derived below (0-100)
);

CREATE TABLE warehouses (
    warehouse_id     VARCHAR(10) PRIMARY KEY,
    warehouse_region VARCHAR(30) NOT NULL
);

CREATE TABLE purchase_orders (
    purchase_order_id VARCHAR(10) PRIMARY KEY,
    ordered_at        DATE        NOT NULL,
    expected_at       DATE        NOT NULL,
    received_at       DATE,                  -- NULL for open / cancelled orders
    status            VARCHAR(15) NOT NULL,  -- received / partial / open / cancelled
    supplier_id       VARCHAR(10) NOT NULL,
    warehouse_id      VARCHAR(10) NOT NULL,
    line_count        INT         NOT NULL,  -- number of product lines on the PO
    quantity_ordered  INT         NOT NULL,
    quantity_received INT         NOT NULL,
    order_value       DECIMAL(14,2) NOT NULL,
    lead_time_days    INT,                   -- received_at - ordered_at  (NULL if not received)
    days_late         INT,                   -- received_at - expected_at (<=0 = early/on time)
    FOREIGN KEY (supplier_id) REFERENCES suppliers(supplier_id),
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id)
);







































-- Derive supplier lead time and reliability from actual delivery behaviour
-- lead time   = average days between order date and receipt date
-- reliability = % of delivered orders received no more than 3 days after the expected date
UPDATE suppliers
SET avg_lead_time_days = (SELECT ROUND(AVG(po.lead_time_days), 2)
                          FROM purchase_orders po
                          WHERE po.supplier_id = suppliers.supplier_id
                            AND po.lead_time_days IS NOT NULL),
    reliability_score  = (SELECT ROUND(100.0 * SUM(CASE WHEN po.days_late <= 3 THEN 1 ELSE 0 END) / COUNT(*), 2)
                          FROM purchase_orders po
                          WHERE po.supplier_id = suppliers.supplier_id
                            AND po.days_late IS NOT NULL);

-- Helper view: every PO except cancelled ones (cancelled orders never became real demand)
CREATE VIEW v_active_po AS
SELECT * FROM purchase_orders WHERE status <> 'cancelled';

-- =====================================================================
-- PART 1 : BASIC DATA UNDERSTANDING
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q1. Understand the supplier base
-- Total suppliers, lead-time and reliability summary (one row)
-- ---------------------------------------------------------------------
SELECT
    COUNT(*)                         AS total_suppliers,
    ROUND(AVG(avg_lead_time_days),2) AS avg_lead_time_days,
    MIN(avg_lead_time_days)          AS min_lead_time_days,
    MAX(avg_lead_time_days)          AS max_lead_time_days,
    ROUND(AVG(reliability_score),2)  AS avg_reliability_score
FROM suppliers;

-- Q1 (b). Suppliers by country, sorted by number of suppliers
SELECT
    supplier_country,
    COUNT(*)                         AS supplier_count,
    ROUND(AVG(avg_lead_time_days),2) AS avg_lead_time_days,
    ROUND(AVG(reliability_score),2)  AS avg_reliability_score
FROM suppliers
GROUP BY supplier_country
ORDER BY supplier_count DESC, supplier_country;


-- ---------------------------------------------------------------------
-- Q3. Analyze warehouses
-- PARTIAL ANSWER: the table has no opening-inventory or product data, so this is a
-- warehouse-level view of what each warehouse has RECEIVED (inbound stock) from purchase orders.
-- ---------------------------------------------------------------------
SELECT
    w.warehouse_id                  AS warehouse_id,
    w.warehouse_region              AS region,
    COUNT(DISTINCT po.supplier_id)  AS suppliers_served,
    SUM(po.line_count)              AS product_lines_received,
    SUM(po.quantity_received)       AS total_inbound_quantity
FROM warehouses w
JOIN v_active_po po ON po.warehouse_id = w.warehouse_id
GROUP BY w.warehouse_id, w.warehouse_region
ORDER BY total_inbound_quantity DESC;


-- ---------------------------------------------------------------------
-- Q4. Classify suppliers using CASE (reliability score)
-- High >= 45 ; Medium 35 to <45 ; Low < 35  (thresholds chosen from the 25-55 score range)
-- ---------------------------------------------------------------------
SELECT
    CASE
        WHEN reliability_score >= 45 THEN 'High Reliability'
        WHEN reliability_score >= 35 THEN 'Medium Reliability'
        ELSE 'Low Reliability'
    END                              AS reliability_class,
    COUNT(*)                         AS supplier_count,
    ROUND(AVG(reliability_score),2)  AS avg_score
FROM suppliers
GROUP BY
    CASE
        WHEN reliability_score >= 45 THEN 'High Reliability'
        WHEN reliability_score >= 35 THEN 'Medium Reliability'
        ELSE 'Low Reliability'
    END
ORDER BY supplier_count DESC;


-- =====================================================================
-- PART 2 : JOINS & PURCHASING ANALYSIS
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q5. Analyze purchase orders per supplier (cancelled POs excluded)
-- ---------------------------------------------------------------------
SELECT
    s.supplier_id,
    s.supplier_country,
    COUNT(po.purchase_order_id)         AS purchase_orders,
    SUM(po.quantity_ordered)            AS total_quantity_ordered,
    ROUND(AVG(po.quantity_ordered),1)   AS avg_order_quantity,
    ROUND(SUM(po.order_value),2)        AS total_po_value
FROM suppliers s
JOIN v_active_po po ON po.supplier_id = s.supplier_id
GROUP BY s.supplier_id, s.supplier_country
ORDER BY total_quantity_ordered DESC
LIMIT 20;   -- top 20 of 250 suppliers shown; remove LIMIT for the full list


-- ---------------------------------------------------------------------
-- Q6. Analyze supplier performance + flag high volume / low reliability
-- High volume = above average supplier volume ; low reliability = below average score
-- ---------------------------------------------------------------------
SELECT
    s.supplier_id,
    s.supplier_country,
    s.avg_lead_time_days,
    s.reliability_score,
    COUNT(po.purchase_order_id)  AS purchase_orders,
    SUM(po.quantity_ordered)     AS total_quantity_ordered,
    CASE
        WHEN SUM(po.quantity_ordered) > (SELECT AVG(t.q) FROM (SELECT SUM(quantity_ordered) AS q
                                                                FROM v_active_po GROUP BY supplier_id) t)
         AND s.reliability_score < (SELECT AVG(reliability_score) FROM suppliers)
        THEN 'HIGH VOLUME / LOW RELIABILITY'
        ELSE 'OK'
    END AS volume_reliability_flag
FROM suppliers s
JOIN v_active_po po ON po.supplier_id = s.supplier_id
GROUP BY s.supplier_id, s.supplier_country, s.avg_lead_time_days, s.reliability_score
HAVING SUM(po.quantity_ordered) > (SELECT AVG(t.q) FROM (SELECT SUM(quantity_ordered) AS q
                                                          FROM v_active_po GROUP BY supplier_id) t)
   AND s.reliability_score < (SELECT AVG(reliability_score) FROM suppliers)
ORDER BY total_quantity_ordered DESC;

-- Q6 (b). How much purchase volume sits with high-volume / low-reliability suppliers
WITH sv AS (
    SELECT s.supplier_id, s.reliability_score, SUM(po.quantity_ordered) AS q
    FROM suppliers s JOIN v_active_po po ON po.supplier_id = s.supplier_id
    GROUP BY s.supplier_id, s.reliability_score
)
SELECT
    COUNT(*)                                             AS flagged_suppliers,
    SUM(q)                                               AS flagged_quantity,
    ROUND(100.0 * SUM(q) / (SELECT SUM(q) FROM sv), 2)   AS pct_of_total_quantity
FROM sv
WHERE q > (SELECT AVG(q) FROM sv)
  AND reliability_score < (SELECT AVG(reliability_score) FROM suppliers);


-- ---------------------------------------------------------------------
-- Q8. Supplier lead-time performance (CASE)
-- Thresholds from the dataset: "Fast" = lead time <= average of all suppliers,
-- "Reliable" = reliability score >= average of all suppliers
-- ---------------------------------------------------------------------
SELECT
    s.supplier_id,
    s.avg_lead_time_days,
    s.reliability_score,
    SUM(po.quantity_ordered) AS total_quantity_ordered,
    CASE
        WHEN s.avg_lead_time_days <= (SELECT AVG(avg_lead_time_days) FROM suppliers)
         AND s.reliability_score  >= (SELECT AVG(reliability_score)  FROM suppliers) THEN 'Fast & Reliable'
        WHEN s.avg_lead_time_days <= (SELECT AVG(avg_lead_time_days) FROM suppliers) THEN 'Fast but Less Reliable'
        WHEN s.reliability_score  >= (SELECT AVG(reliability_score)  FROM suppliers) THEN 'Slow but Reliable'
        ELSE 'Slow & Less Reliable'
    END AS lead_time_class
FROM suppliers s
JOIN v_active_po po ON po.supplier_id = s.supplier_id
GROUP BY s.supplier_id, s.avg_lead_time_days, s.reliability_score
ORDER BY lead_time_class, total_quantity_ordered DESC
LIMIT 20;

-- Q8 (b). How many suppliers fall in each class
SELECT lead_time_class, COUNT(*) AS suppliers, ROUND(AVG(avg_lead_time_days),1) AS avg_lead, ROUND(AVG(reliability_score),1) AS avg_rel
FROM (
    SELECT s.supplier_id, s.avg_lead_time_days, s.reliability_score,
        CASE
            WHEN s.avg_lead_time_days <= (SELECT AVG(avg_lead_time_days) FROM suppliers)
             AND s.reliability_score  >= (SELECT AVG(reliability_score)  FROM suppliers) THEN 'Fast & Reliable'
            WHEN s.avg_lead_time_days <= (SELECT AVG(avg_lead_time_days) FROM suppliers) THEN 'Fast but Less Reliable'
            WHEN s.reliability_score  >= (SELECT AVG(reliability_score)  FROM suppliers) THEN 'Slow but Reliable'
            ELSE 'Slow & Less Reliable'
        END AS lead_time_class
    FROM suppliers s
) c
GROUP BY lead_time_class
ORDER BY suppliers DESC;


-- =====================================================================
-- PART 3 : INVENTORY (warehouse-level, partial)
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q11. Analyze inventory movement by warehouse and movement type
-- PARTIAL ANSWER: there is no stock-movement table. Each purchase order is treated as one
-- inbound movement; movement type = PO status (received / partial = receipts, open = pending inbound).
-- quantity moved = quantity_received (received, partial) or quantity_ordered (open). Cancelled POs excluded.
-- ---------------------------------------------------------------------
SELECT
    w.warehouse_id,
    po.status                               AS movement_type,
    SUM(CASE WHEN po.status = 'open' THEN po.quantity_ordered ELSE po.quantity_received END)       AS total_quantity_moved,
    COUNT(*)                                AS number_of_movements,
    ROUND(AVG(CASE WHEN po.status = 'open' THEN po.quantity_ordered ELSE po.quantity_received END),1) AS avg_movement_quantity
FROM warehouses w
JOIN v_active_po po ON po.warehouse_id = w.warehouse_id
GROUP BY w.warehouse_id, po.status
ORDER BY total_quantity_moved DESC
LIMIT 15;

-- Q11 (b). Warehouses with the highest overall movement volume
SELECT
    w.warehouse_id,
    w.warehouse_region,
    SUM(CASE WHEN po.status = 'open' THEN po.quantity_ordered ELSE po.quantity_received END) AS total_movement,
    COUNT(*) AS number_of_movements
FROM warehouses w
JOIN v_active_po po ON po.warehouse_id = w.warehouse_id
GROUP BY w.warehouse_id, w.warehouse_region
ORDER BY total_movement DESC;


-- ---------------------------------------------------------------------
-- Q12. Warehouses with unusual (above-average) movement (subquery in HAVING)
-- PARTIAL ANSWER: uses the warehouse-level movement defined in Q11
-- ---------------------------------------------------------------------
SELECT
    w.warehouse_id,
    SUM(CASE WHEN po.status = 'open' THEN po.quantity_ordered ELSE po.quantity_received END) AS total_movement,
    ROUND((SELECT AVG(t.m) FROM (SELECT SUM(CASE WHEN status = 'open' THEN quantity_ordered ELSE quantity_received END) AS m
                                  FROM v_active_po GROUP BY warehouse_id) t), 0) AS overall_avg_movement,
    ROUND(SUM(CASE WHEN po.status = 'open' THEN po.quantity_ordered ELSE po.quantity_received END)
        - (SELECT AVG(t.m) FROM (SELECT SUM(CASE WHEN status = 'open' THEN quantity_ordered ELSE quantity_received END) AS m
                                  FROM v_active_po GROUP BY warehouse_id) t), 0) AS difference_from_avg
FROM warehouses w
JOIN v_active_po po ON po.warehouse_id = w.warehouse_id
GROUP BY w.warehouse_id
HAVING SUM(CASE WHEN po.status = 'open' THEN po.quantity_ordered ELSE po.quantity_received END)
     > (SELECT AVG(t.m) FROM (SELECT SUM(CASE WHEN status = 'open' THEN quantity_ordered ELSE quantity_received END) AS m
                               FROM v_active_po GROUP BY warehouse_id) t)
ORDER BY difference_from_avg DESC;


-- =====================================================================
-- PART 4 : SUBQUERIES
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q14. Suppliers with above-average order volume
-- ---------------------------------------------------------------------
SELECT
    sv.supplier_id,
    sv.total_quantity_ordered,
    ROUND((SELECT AVG(q) FROM (SELECT SUM(quantity_ordered) AS q FROM v_active_po GROUP BY supplier_id) a), 1) AS avg_supplier_quantity
FROM (SELECT supplier_id, SUM(quantity_ordered) AS total_quantity_ordered
      FROM v_active_po GROUP BY supplier_id) sv
WHERE sv.total_quantity_ordered > (SELECT AVG(q) FROM (SELECT SUM(quantity_ordered) AS q
                                                       FROM v_active_po GROUP BY supplier_id) b)
ORDER BY sv.total_quantity_ordered DESC
LIMIT 15;

-- Q14 (b). How many suppliers are above average
SELECT COUNT(*) AS suppliers_above_average
FROM (SELECT supplier_id, SUM(quantity_ordered) AS q FROM v_active_po GROUP BY supplier_id) sv
WHERE q > (SELECT AVG(q2) FROM (SELECT SUM(quantity_ordered) AS q2 FROM v_active_po GROUP BY supplier_id) z);


-- ---------------------------------------------------------------------
-- Q15. High-risk suppliers: reliability BELOW average AND lead time ABOVE average
-- ---------------------------------------------------------------------
SELECT
    s.supplier_id,
    s.supplier_country,
    s.reliability_score,
    s.avg_lead_time_days,
    (SELECT ROUND(AVG(reliability_score),2)  FROM suppliers) AS overall_avg_reliability,
    (SELECT ROUND(AVG(avg_lead_time_days),2) FROM suppliers) AS overall_avg_lead_time
FROM suppliers s
WHERE s.reliability_score  < (SELECT AVG(reliability_score)  FROM suppliers)
  AND s.avg_lead_time_days > (SELECT AVG(avg_lead_time_days) FROM suppliers)
ORDER BY s.reliability_score ASC, s.avg_lead_time_days DESC
LIMIT 15;

-- Q15 (b). Count of high-risk suppliers
SELECT COUNT(*) AS high_risk_suppliers
FROM suppliers
WHERE reliability_score  < (SELECT AVG(reliability_score)  FROM suppliers)
  AND avg_lead_time_days > (SELECT AVG(avg_lead_time_days) FROM suppliers);


-- =====================================================================
-- PART 5 : CTEs
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q16. Supplier performance summary with priority classification (CTE)
-- Logic: High Priority  = reliability below average AND lead time above average
--                         (slow AND unreliable -> needs action)
--        Monitor        = exactly one of the two is worse than average
--        Stable         = reliability at/above average AND lead time at/below average
-- ---------------------------------------------------------------------
WITH supplier_summary AS (
    SELECT
        s.supplier_id,
        s.supplier_country,
        COUNT(po.purchase_order_id)  AS purchase_orders,
        SUM(po.quantity_ordered)     AS total_quantity_ordered,
        ROUND(AVG(po.quantity_ordered),1) AS avg_order_quantity,
        s.avg_lead_time_days,
        s.reliability_score
    FROM suppliers s
    JOIN v_active_po po ON po.supplier_id = s.supplier_id
    GROUP BY s.supplier_id, s.supplier_country, s.avg_lead_time_days, s.reliability_score
),
benchmarks AS (
    SELECT AVG(avg_lead_time_days) AS avg_lead, AVG(reliability_score) AS avg_rel FROM suppliers
)
SELECT
    ss.*,
    CASE
        WHEN ss.reliability_score <  b.avg_rel AND ss.avg_lead_time_days >  b.avg_lead THEN 'High Priority'
        WHEN ss.reliability_score >= b.avg_rel AND ss.avg_lead_time_days <= b.avg_lead THEN 'Stable'
        ELSE 'Monitor'
    END AS supplier_priority
FROM supplier_summary ss
CROSS JOIN benchmarks b
ORDER BY CASE
            WHEN ss.reliability_score <  b.avg_rel AND ss.avg_lead_time_days >  b.avg_lead THEN 1
            WHEN ss.reliability_score >= b.avg_rel AND ss.avg_lead_time_days <= b.avg_lead THEN 3
            ELSE 2 END,
         ss.total_quantity_ordered DESC
LIMIT 15;

-- Q16 (b). Count of suppliers per priority class
WITH supplier_summary AS (
    SELECT s.supplier_id, s.avg_lead_time_days, s.reliability_score
    FROM suppliers s
),
benchmarks AS (
    SELECT AVG(avg_lead_time_days) AS avg_lead, AVG(reliability_score) AS avg_rel FROM suppliers
)
SELECT
    CASE
        WHEN ss.reliability_score <  b.avg_rel AND ss.avg_lead_time_days >  b.avg_lead THEN 'High Priority'
        WHEN ss.reliability_score >= b.avg_rel AND ss.avg_lead_time_days <= b.avg_lead THEN 'Stable'
        ELSE 'Monitor'
    END AS supplier_priority,
    COUNT(*) AS suppliers
FROM supplier_summary ss CROSS JOIN benchmarks b
GROUP BY 1
ORDER BY suppliers DESC;


-- =====================================================================
-- PART 6 : WINDOW FUNCTIONS
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q18. Rank suppliers within each country (RANK + PARTITION BY)
-- ---------------------------------------------------------------------
WITH supplier_qty AS (
    SELECT s.supplier_id, s.supplier_country, SUM(po.quantity_ordered) AS quantity_ordered
    FROM suppliers s
    JOIN v_active_po po ON po.supplier_id = s.supplier_id
    GROUP BY s.supplier_id, s.supplier_country
),
ranked_suppliers AS (
    SELECT
        supplier_id,
        supplier_country,
        quantity_ordered,
        RANK() OVER (PARTITION BY supplier_country ORDER BY quantity_ordered DESC) AS rank_within_country
    FROM supplier_qty
)
SELECT *
FROM ranked_suppliers
WHERE rank_within_country <= 3      -- top 3 per country; remove the filter to list all 250 suppliers
ORDER BY supplier_country, rank_within_country;


-- ---------------------------------------------------------------------
-- Q19. Compare within a category (warehouses within region)
-- PARTIAL ANSWER: no product/category data, so warehouses are compared within their REGION
-- (two warehouses per region) using window functions.
-- ---------------------------------------------------------------------
WITH wh_qty AS (
    SELECT w.warehouse_id, w.warehouse_region, SUM(po.quantity_ordered) AS total_quantity_ordered
    FROM warehouses w
    JOIN v_active_po po ON po.warehouse_id = w.warehouse_id
    GROUP BY w.warehouse_id, w.warehouse_region
)
SELECT
    warehouse_id,
    warehouse_region,
    total_quantity_ordered,
    ROUND(AVG(total_quantity_ordered) OVER (PARTITION BY warehouse_region), 1)                        AS region_avg_quantity,
    ROUND(total_quantity_ordered - AVG(total_quantity_ordered) OVER (PARTITION BY warehouse_region), 1) AS diff_from_region_avg,
    RANK() OVER (PARTITION BY warehouse_region ORDER BY total_quantity_ordered DESC)                  AS rank_within_region
FROM wh_qty
ORDER BY warehouse_region, rank_within_region;


-- =====================================================================
-- PART 7 : ADVANCED SUPPLY CHAIN ANALYSIS
-- =====================================================================

-- ---------------------------------------------------------------------
-- Q20. SUPPLY CHAIN PERFORMANCE REPORT  (uses CTEs + window function + CASE)
-- KPIs per supplier: POs, quantity, lead time, reliability, product lines,
-- warehouses served, inventory-risk indicators (fill rate, cancel rate, open backlog),
-- rank within country, then classification and attention flag.
-- ---------------------------------------------------------------------
WITH supplier_kpi AS (
    SELECT
        s.supplier_id,
        s.supplier_country,
        s.avg_lead_time_days,
        s.reliability_score,
        COUNT(*)                                   AS total_purchase_orders,
        SUM(po.quantity_ordered)                   AS total_quantity_ordered,
        SUM(po.line_count)                         AS product_lines_supplied,
        COUNT(DISTINCT po.warehouse_id)            AS warehouses_served,
        ROUND(100.0 * SUM(CASE WHEN po.status IN ('received','partial') THEN po.quantity_received ELSE 0 END)
              / NULLIF(SUM(CASE WHEN po.status IN ('received','partial') THEN po.quantity_ordered ELSE 0 END), 0), 2) AS fill_rate_pct,
        ROUND(100.0 * SUM(CASE WHEN po.status = 'open' THEN 1 ELSE 0 END) / COUNT(*), 2)      AS open_order_pct,
        ROUND(100.0 * SUM(CASE WHEN po.status = 'partial' THEN 1 ELSE 0 END) / COUNT(*), 2)   AS partial_order_pct
    FROM suppliers s
    JOIN v_active_po po ON po.supplier_id = s.supplier_id
    GROUP BY s.supplier_id, s.supplier_country, s.avg_lead_time_days, s.reliability_score
),
benchmarks AS (
    SELECT AVG(avg_lead_time_days) AS avg_lead,
           AVG(reliability_score)  AS avg_rel,
           AVG(total_quantity_ordered) AS avg_qty,
           AVG(fill_rate_pct)      AS avg_fill
    FROM supplier_kpi
),
ranked AS (
    SELECT
        k.*,
        RANK() OVER (PARTITION BY k.supplier_country ORDER BY k.total_quantity_ordered DESC) AS rank_in_country,
        CASE
            WHEN k.avg_lead_time_days <= b.avg_lead AND k.reliability_score >= b.avg_rel THEN 'Fast & Reliable'
            WHEN k.avg_lead_time_days <= b.avg_lead                                      THEN 'Fast but Less Reliable'
            WHEN k.reliability_score  >= b.avg_rel                                       THEN 'Slow but Reliable'
            ELSE 'Slow & Less Reliable'
        END AS supplier_class,
        CASE
            WHEN k.total_quantity_ordered > b.avg_qty AND k.reliability_score < b.avg_rel THEN 'ATTENTION: high volume, low reliability'
            WHEN k.reliability_score < b.avg_rel AND k.avg_lead_time_days > b.avg_lead     THEN 'ATTENTION: slow and unreliable'
            WHEN k.fill_rate_pct < b.avg_fill AND k.total_quantity_ordered > b.avg_qty     THEN 'ATTENTION: high volume, low fill rate'
            ELSE 'No action'
        END AS management_flag
    FROM supplier_kpi k CROSS JOIN benchmarks b
)
SELECT *
FROM ranked
WHERE management_flag <> 'No action'
ORDER BY total_quantity_ordered DESC
LIMIT 15;

-- Q20 (b). Supplier class and management-attention summary
WITH supplier_kpi AS (
    SELECT s.supplier_id, s.avg_lead_time_days, s.reliability_score, SUM(po.quantity_ordered) AS total_quantity_ordered,
           100.0 * SUM(CASE WHEN po.status IN ('received','partial') THEN po.quantity_received ELSE 0 END)
           / NULLIF(SUM(CASE WHEN po.status IN ('received','partial') THEN po.quantity_ordered ELSE 0 END), 0) AS fill_rate_pct
    FROM suppliers s JOIN v_active_po po ON po.supplier_id = s.supplier_id
    GROUP BY s.supplier_id, s.avg_lead_time_days, s.reliability_score
),
benchmarks AS (
    SELECT AVG(avg_lead_time_days) AS avg_lead, AVG(reliability_score) AS avg_rel, AVG(total_quantity_ordered) AS avg_qty, AVG(fill_rate_pct) AS avg_fill
    FROM supplier_kpi
)
SELECT
    CASE
        WHEN k.avg_lead_time_days <= b.avg_lead AND k.reliability_score >= b.avg_rel THEN 'Fast & Reliable'
        WHEN k.avg_lead_time_days <= b.avg_lead THEN 'Fast but Less Reliable'
        WHEN k.reliability_score  >= b.avg_rel  THEN 'Slow but Reliable'
        ELSE 'Slow & Less Reliable'
    END AS supplier_class,
    COUNT(*) AS suppliers,
    SUM(k.total_quantity_ordered) AS quantity_ordered,
    ROUND(100.0 * SUM(k.total_quantity_ordered) / (SELECT SUM(total_quantity_ordered) FROM supplier_kpi), 1) AS pct_of_volume,
    SUM(CASE WHEN k.total_quantity_ordered > b.avg_qty AND k.reliability_score < b.avg_rel THEN 1 ELSE 0 END) AS high_volume_low_reliability
FROM supplier_kpi k CROSS JOIN benchmarks b
GROUP BY 1
ORDER BY suppliers DESC;

-- Q20 (c). Concentration KPI: share of total volume held by the top 10% of suppliers (25 of 250)
WITH sv AS (
    SELECT supplier_id, SUM(quantity_ordered) AS q,
           RANK() OVER (ORDER BY SUM(quantity_ordered) DESC) AS rnk
    FROM v_active_po GROUP BY supplier_id
)
SELECT
    ROUND(100.0 * SUM(CASE WHEN rnk <= 25 THEN q ELSE 0 END) / SUM(q), 2) AS top25_suppliers_share_pct,
    COUNT(*) AS suppliers
FROM sv;

-- Q20 (d). Order-status mix and warehouse inbound risk (inventory-related KPI)
SELECT
    status,
    COUNT(*)                         AS purchase_orders,
    ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM purchase_orders), 2) AS pct_of_pos,
    SUM(quantity_ordered)            AS quantity_ordered,
    SUM(quantity_received)           AS quantity_received
FROM purchase_orders
GROUP BY status
ORDER BY purchase_orders DESC;

-- Q20 (e). Overall supply chain KPIs
SELECT
    COUNT(*)                                                            AS active_purchase_orders,
    SUM(quantity_ordered)                                               AS total_quantity_ordered,
    ROUND(SUM(order_value),2)                                           AS total_order_value,
    ROUND(AVG(lead_time_days),2)                                        AS avg_actual_lead_time_days,
    ROUND(100.0 * SUM(CASE WHEN days_late <= 0 THEN 1 ELSE 0 END) / COUNT(days_late), 2) AS on_time_pct,
    ROUND(100.0 * SUM(CASE WHEN days_late <= 3 THEN 1 ELSE 0 END) / COUNT(days_late), 2) AS on_time_within_3d_pct,
    ROUND(AVG(days_late),2)                                             AS avg_days_late,
    ROUND(100.0 * SUM(quantity_received) / SUM(CASE WHEN status IN ('received','partial') THEN quantity_ordered ELSE 0 END), 2) AS fill_rate_pct
FROM v_active_po;

